# Root-owned self-contained incremental direct-v7 attempt-2 entry. Existing v7 package remains intact; no remote deletion.
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$stage='D:\Claude\swiftright\.factory-work\hosts\custom-layout-colors'
$pkg=Join-Path $stage 'package';$plan=Join-Path $pkg 'plan-prebuild-r5.json';$builder=Join-Path $stage 'freshbuilder-r5.ps1'
function Hash([string]$p){$f=Get-Item -LiteralPath $p -Force;if($f.PSIsContainer -or ($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $f.Length -gt 67108864){throw 'bounded regular file required'};(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
if(-not (Test-Path -LiteralPath $pkg -PathType Container)){throw 'existing v7 package required; do not initialize new stage'}
if((Hash (Join-Path $pkg 'plan.json')) -cne '6eae21b6d888c3c7f8abd7e564c62d259eafa45cc7d93ac185ce46da6fea701c'){throw 'existing v7 package plan drift'}
if(@(Get-Process swift,swiftc,swift-build,clang,FactoryProbe -ErrorAction SilentlyContinue).Count){throw 'compiler/native lane busy'}
if((Get-Content -LiteralPath 'D:\Claude\desktop.lock' -Raw).Trim() -cne 'free'){throw 'desktop busy'}
$planBytes=[Convert]::FromBase64String('')
if(Test-Path -LiteralPath $plan){if((Hash $plan) -cne 'ecf9ba5115bcafae8db6de14d1998201f2b5b56634d9177d18cad2ffa9547337'){throw 'fresh remote plan drift'}}else{[IO.File]::WriteAllBytes($plan,$planBytes)}
if((Hash $plan) -cne 'ecf9ba5115bcafae8db6de14d1998201f2b5b56634d9177d18cad2ffa9547337'){throw 'fresh remote plan hash drift'}
$builderBytes=[Convert]::FromBase64String('')
if(Test-Path -LiteralPath $builder){if((Hash $builder) -cne '7b9b26f0693665fe3078ab2a9de0af436b5a3f65384806fc06c72a3b28e4574c'){throw 'fresh remote builder drift'}}else{[IO.File]::WriteAllBytes($builder,$builderBytes)}
if((Hash $builder) -cne '7b9b26f0693665fe3078ab2a9de0af436b5a3f65384806fc06c72a3b28e4574c'){throw 'fresh remote builder hash drift'}
if((Get-Content -LiteralPath 'D:\Claude\desktop.lock' -Raw).Trim() -cne 'free'){throw 'desktop changed during staging'}
$preflight=& $builder -PlanPath $plan -PlanSha256 'ecf9ba5115bcafae8db6de14d1998201f2b5b56634d9177d18cad2ffa9547337' -Phase prebuild -Attempt 2 -PreflightOnly
$preflightRecord=$preflight|ConvertFrom-Json
if($preflightRecord.status -cne 'passed' -or $preflightRecord.compilerStarted -ne $false -or $preflightRecord.nativeActions -ne 0 -or $preflightRecord.memoryCapBytes -ne 1073741824){throw 'prebuild attempt-2 preflight status failed'}
$preflight|Set-Content -LiteralPath (Join-Path $stage 'prebuild-preflight-r5-attempt2.json') -Encoding UTF8
& $builder -PlanPath $plan -PlanSha256 'ecf9ba5115bcafae8db6de14d1998201f2b5b56634d9177d18cad2ffa9547337' -Phase prebuild -Attempt 2
